import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"蓝图压缩与产线设计成果","description":"","frontmatter":{"translationSource":{"title":"蓝图压缩与产线设计成果","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=t4CC9yDWIry334jvJw9Dqd","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/blueprint-compression-and-production-line-design-results"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/blueprint-compression-and-production-line-design-results"}]]},"headers":[],"relativePath":"zh/blueprint-compression-and-production-line-design-results.md","filePath":"zh/page-t4CC9yDWIry334jvJw9Dqd.md"}'),n={name:"zh/blueprint-compression-and-production-line-design-results.md"};function i(s,e,d,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="蓝图压缩与产线设计成果" tabindex="-1">蓝图压缩与产线设计成果 <a class="header-anchor" href="#蓝图压缩与产线设计成果" aria-label="Permalink to &quot;蓝图压缩与产线设计成果&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-14. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>t4CC9yDWIry334jvJw9Dqd</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=t4CC9yDWIry334jvJw9Dqd" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>出于方便，添加此引用便于跳转<a href="/endfield-skydoc/zh/factory-production-plans-logic-and-layout-implementation-across-versions">各版本基建生产方案及逻辑与布局实现研究</a></p><p>原则上，本页前半部分应当用于放置压缩后模块化产线蓝图图像及蓝图码，并标明蓝图效果与作者。如果作者无法溯源，可以标明为 未知作者 。后半部分可以放产线设计。</p><p><span id="source-block-WeY8IOk8p864NNCg600NZb"></span></p><h2 id="普通蓝图-通用生产条件" tabindex="-1">普通蓝图（通用生产条件 <a class="header-anchor" href="#普通蓝图-通用生产条件" aria-label="Permalink to &quot;普通蓝图（通用生产条件&quot;">​</a></h2><p><span id="source-block-l4MZ9YpUH8AsfLpkiBejAp"></span></p><h3 id="常见-常用标签" tabindex="-1">常见\\常用标签 <a class="header-anchor" href="#常见-常用标签" aria-label="Permalink to &quot;常见\\常用标签&quot;">​</a></h3><p>无箱：不使用箱子，使用存货口存入产物。</p><p>自启动：指息壤固气转化为息壤气和采种循环这类增值循环的最初输入，蓝图可以自动从仓库自动取货填入，而不需要玩家手动填入。</p><p>加压入库：指产物使用多个存入口存入，使得最大入库速度大于生产速度，满速生产时空仓机器中遗留的堆积产物可以缓慢输出到仓库来减少。</p><p>真\\伪%d%d（一串数字）：蓝图占地，真表示管道无需借道存储线上。例如5024=50x24占地。</p><p>暗管：使用暗管进行蓝图内外液体的输入输出。</p><p>压缩率/空间利用率：（必要空间：除去物流元件、无关设备、供电设备后，剩余设备的体积之和）（占用空间：模块占用的地盘最大长乘最大宽）互为倒数，通常&gt;1为占用空间/必要空间，&lt;1为必要空间/占用空间。对于&gt;1的压缩率来说，数字越小，代表压缩水平越高，通常极限为1.4~1.6，越是复杂的模块，极限就越大。</p><p><span id="source-block-gLPzoNfu3gcpxzlDGlxGAx"></span></p><h2 id="特殊蓝图-单蓝图附带讲解" tabindex="-1">特殊蓝图（单蓝图附带讲解 <a class="header-anchor" href="#特殊蓝图-单蓝图附带讲解" aria-label="Permalink to &quot;特殊蓝图（单蓝图附带讲解&quot;">​</a></h2><p><a href="/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals">基于时钟信号的单烘炉重息壤方案</a> · <a href="/endfield-skydoc/zh/separator-core-module">分离芯模块</a></p></div>',1)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
